def ReFormatString(S: str, K: int) -> str:
    cleaned = [c.upper() for c in S if c != '-']
    n = len(cleaned)
    if n == 0:
        return ""

    remainder = n % K
    result = []

    if remainder > 0:
        result.append("".join(cleaned[:remainder]))
        start = remainder
    else:
        start = 0

    while start < n:
        if result:
            result.append("-")
        result.append("".join(cleaned[start:start+K]))
        start += K

    return "".join(result)
